/**
 * The font files of the new look, keyed by the family name the styles use
 * (tokens.ts → `fonts`). Loaded once at start in app/_layout.tsx.
 *
 * Kept apart from tokens.ts so the tokens stay plain data (tests read them
 * without bundling .ttf files). The files themselves are checked in
 * src/design/__tests__/fonts.test.ts — above all that each has a PostScript
 * name: iOS draws the icon font as "?" without one.
 *
 * The icon font is generated by scripts/build-icon-font.py — never edit it by hand.
 */
import { fonts } from './tokens';

export const fontFiles = {
  [fonts.display]: require('../../assets/fonts/Fraunces-SemiBold.ttf'),
  [fonts.displayItalic]: require('../../assets/fonts/Fraunces-SemiBoldItalic.ttf'),
  [fonts.regular]: require('../../assets/fonts/Figtree-Regular.ttf'),
  [fonts.medium]: require('../../assets/fonts/Figtree-Medium.ttf'),
  [fonts.semibold]: require('../../assets/fonts/Figtree-SemiBold.ttf'),
  [fonts.bold]: require('../../assets/fonts/Figtree-Bold.ttf'),
  [fonts.icons]: require('../../assets/fonts/SelfRiseIcons.ttf'),
};
